package de.nevergate.city;
import de.nevergate.city.economy.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraftforge.gametest.GameTestHolder;
@GameTestHolder(value="ng_city",namespace="ng_city")
public final class EconomyGameTests {
 static ServerPlayer player(GameTestHelper h){var p=new ServerPlayer(h.getLevel().getServer(),h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"NGTester"),ClientInformation.createDefault()){
 @Override public void sendSystemMessage(net.minecraft.network.chat.Component message){}
 @Override public void displayClientMessage(net.minecraft.network.chat.Component message,boolean actionBar){}
 };p.getAbilities().mayBuild=true;var o=CityGameTests.origin(h);p.setPos(o.getX(),o.getY(),o.getZ()-4);return p;}
 static EconomyData.Account account(GameTestHelper h,ServerPlayer p){Banking.open(p);CardPin.initialise(p,"0427");return EconomyData.get(h.getLevel()).accounts.get(p.getUUID());}
 static EconomyData.Hotel hotel(GameTestHelper h){var l=h.getLevel();var origin=CityGameTests.origin(h);var bp=new BuildingPlan(BuildingKind.HOTEL);var plan=bp.transformed(origin,Direction.SOUTH);CityGameTests.support(l,plan);Placement.apply(l,plan,null,Direction.UP);var npc=Placement.employee(l,BuildingKind.HOTEL,bp.employeePos(origin,Direction.SOUTH),Direction.SOUTH,UUID.randomUUID());l.addFreshEntity(npc);return HotelService.ensure(npc);}
 static void ok(GameTestHelper h,boolean value,String msg){h.assertTrue(value,msg);}
 @GameTest(batch="economy0",template="ng_city:empty",timeoutTicks=100) public static void accountOnlyOnceAndPlayerBinding(GameTestHelper h){var p=player(h);var a=account(h,p);long balance=a.balance;Banking.open(p);ok(h,a.balance==balance&&balance==2500,"Start credit repeated");ok(h,Money.has(p,NgCity.WALLET.get())&&Money.card(p),"Bound wallet/card missing");var other=player(h);other.getInventory().add(Money.bound(NgCity.CARD.get(),p));account(h,other);other.getInventory().clearContent();other.getInventory().add(Money.bound(NgCity.CARD.get(),p));ok(h,!Money.card(other),"Foreign card authorized");h.succeed();}
 @GameTest(batch="economy0",template="ng_city:empty",timeoutTicks=100) public static void replacementRevokesOldCardKeepsWallet(GameTestHelper h){var p=player(h);var a=account(h,p);var old=a.card;a.wallet.set(0,new ItemStack(NgCity.CASH.get(0).get(),3));Banking.replace(p,true);ok(h,!old.equals(a.card),"Old card not revoked");Banking.replace(p,false);ok(h,Money.total(a.wallet)==1500,"Replacement lost money");h.succeed();}
 @GameTest(batch="economy0",template="ng_city:empty",timeoutTicks=100) public static void withdrawDepositAndExactChange(GameTestHelper h){var p=player(h);var a=account(h,p);Banking.withdraw(p,1000);ok(h,a.balance==1500&&Money.total(Money.inventory(p))==1000,"ATM mismatch");Banking.deposit(p);ok(h,a.balance==2500&&Money.total(Money.inventory(p))==0,"Deposit mismatch");a.wallet.set(0,new ItemStack(NgCity.CASH.get(0).get()));ok(h,Money.payCash(p,51,true)&&Money.total(a.wallet)==449,"Incorrect exact change");h.succeed();}
 @GameTest(batch="economy0",template="ng_city:empty",timeoutTicks=100) public static void insufficientCashDoesNotMutate(GameTestHelper h){var p=player(h);var a=account(h,p);a.wallet.set(0,new ItemStack(NgCity.CASH.get(7).get()));ok(h,!Money.payCash(p,2,true)&&Money.total(a.wallet)==1,"Cash loss after refusal");h.succeed();}
 @GameTest(batch="economy1",template="ng_city:empty",timeoutTicks=100) public static void fullInventoryWithdrawDoesNotDebit(GameTestHelper h){var p=player(h);var a=account(h,p);for(int i=2;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));long before=a.balance;Banking.withdraw(p,100);ok(h,a.balance==before,"Debited full inventory");h.succeed();}
 @GameTest(batch="economy1",template="ng_city:empty",timeoutTicks=100) public static void buyDiamondsToBankAndCashSharesLimit(GameTestHelper h){var p=player(h);var a=account(h,p);p.getInventory().add(new ItemStack(Items.DIAMOND_BLOCK,10));Banking.sell(p,new ItemStack(Items.DIAMOND_BLOCK),false);ok(h,a.balance==7000,"Diamond block payout incorrect: "+a.balance);p.getInventory().add(new ItemStack(Items.DIAMOND,350));Banking.sell(p,new ItemStack(Items.DIAMOND),true);ok(h,Money.total(Money.inventory(p))==15500&&a.sold(System.currentTimeMillis())==20000,"Cash/account limits separate");ok(h,p.getInventory().countItem(Items.DIAMOND)==40,"Sold beyond cap");h.succeed();}
 @GameTest(batch="economy1",template="ng_city:empty",timeoutTicks=100) public static void dirtBundlesAndNamedItemsRejected(GameTestHelper h){var p=player(h);var a=account(h,p);p.getInventory().add(new ItemStack(Items.DIRT,63));Banking.sell(p,new ItemStack(Items.DIRT),false);ok(h,p.getInventory().countItem(Items.DIRT)==63&&a.balance==2500,"Fractional dirt sold");p.getInventory().add(new ItemStack(Items.DIRT));Banking.sell(p,new ItemStack(Items.DIRT),false);ok(h,a.balance==2501,"64 dirt must pay ten cents");var named=new ItemStack(Items.DIAMOND);named.setHoverName(net.minecraft.network.chat.Component.literal("Private"));ok(h,BuyPrices.quote(h.getLevel(),named)==null,"Accepted customized item");ok(h,BuyPrices.quote(h.getLevel(),new ItemStack(NgCity.BANK.get()))==null&&BuyPrices.quote(h.getLevel(),new ItemStack(Items.BEDROCK))==null,"Accepted mod/admin item");h.succeed();}
 @GameTest(batch="economy1",template="ng_city:empty",timeoutTicks=100) public static void rollingRealHourLimitExpires(GameTestHelper h){var a=new EconomyData.Account();long now=System.currentTimeMillis();a.sales.add(new EconomyData.Receipt(now-EconomyData.REAL_HOUR,12));a.sales.add(new EconomyData.Receipt(now-10,33));ok(h,a.sold(now)==33,"1h boundary incorrect");h.succeed();}
 @GameTest(batch="economy2",template="ng_city:empty",timeoutTicks=100) public static void hotelRefusesUnpaidAndTooLongBooking(GameTestHelper h){var p=player(h);var a=account(h,p);var hotel=hotel(h);a.balance=0;HotelService.book(p,hotel,0,1,false,"0427");ok(h,hotel.rooms[0].owner==null&&p.getInventory().countItem(NgCity.KEY.get())==0,"Unpaid booking granted");a.balance=2500;HotelService.book(p,hotel,0,8,false,"0427");ok(h,hotel.rooms[0].owner==null&&a.balance==2500,"8-day booking accepted");h.succeed();}
 @GameTest(batch="economy2",template="ng_city:empty",timeoutTicks=100) public static void hotelPaidKeyOnlyOwnRoom(GameTestHelper h){var p=player(h);var a=account(h,p);var hotel=hotel(h);HotelService.book(p,hotel,0,2,false,"0427");ok(h,a.balance==2400&&hotel.rooms[0].owner.equals(p.getUUID()),"Wrong room charge");var key=p.getInventory().items.stream().filter(s->s.is(NgCity.KEY.get())).findFirst().orElseThrow();p.setItemInHand(InteractionHand.MAIN_HAND,key.copy());ok(h,HotelService.key(p,hotel,0)&&!HotelService.key(p,hotel,1),"Key opens wrong room");var other=player(h);other.setItemInHand(InteractionHand.MAIN_HAND,key.copy());ok(h,!HotelService.key(other,hotel,0),"Foreign player used key");long before=a.balance;HotelService.book(p,hotel,0,1,false,"0427");ok(h,a.balance==before,"Double booked occupied room");h.succeed();}
 @GameTest(batch="economy2",template="ng_city:empty",timeoutTicks=100) public static void hotelCashAndDisplay(GameTestHelper h){var p=player(h);var a=account(h,p);var hotel=hotel(h);a.wallet.set(0,new ItemStack(NgCity.CASH.get(0).get()));HotelService.book(p,hotel,1,7,true);ok(h,Money.total(a.wallet)==150&&a.balance==2500,"Wrong cash hotel payment");var be=(HotelDisplayEntity)h.getLevel().getBlockEntity(HotelService.pos(hotel,6,2,7));be.refresh();ok(h,be.occupied[1]&&be.lines[1].contains("7 Tage")&&!be.occupied[0],"Display occupancy missing");h.succeed();}
 @GameTest(batch="economy2",template="ng_city:empty",timeoutTicks=100) public static void expirationInvalidatesKeyAndStoresContents(GameTestHelper h){var p=player(h);account(h,p);var hotel=hotel(h);HotelService.book(p,hotel,0,1,false,"0427");var key=p.getInventory().items.stream().filter(s->s.is(NgCity.KEY.get())).findFirst().orElseThrow();p.setItemInHand(InteractionHand.MAIN_HAND,key.copy());var c=(Container)h.getLevel().getBlockEntity(HotelService.pos(hotel,4,6,12));c.setItem(0,new ItemStack(Items.DIAMOND,7));hotel.rooms[0].until=h.getLevel().getDayTime();HotelService.tick(h.getLevel(),hotel);ok(h,!HotelService.key(p,hotel,0)&&hotel.rooms[0].owner==null,"Expired key valid");ok(h,c.isEmpty()&&hotel.rooms[0].stored.size()==1&&hotel.rooms[0].stored.get(0).items.get(0).getCount()==7,"Items lost on expiration");h.succeed();}
 @GameTest(batch="economy3",template="ng_city:empty",timeoutTicks=100) public static void reclaimChargesDailyFeeAndNeverDuplicates(GameTestHelper h){var p=player(h);var a=account(h,p);var hotel=hotel(h);var bag=new EconomyData.Stored();bag.owner=p.getUUID();bag.since=h.getLevel().getDayTime()-24001;bag.items.add(new ItemStack(Items.DIAMOND,3));hotel.rooms[0].stored.add(bag);HotelService.reclaim(p,hotel,false,false,"0427");ok(h,a.balance==2480&&p.getInventory().countItem(Items.DIAMOND)==3&&hotel.rooms[0].stored.isEmpty(),"Fee/reclaim wrong");HotelService.reclaim(p,hotel,false,false,"0427");ok(h,a.balance==2480&&p.getInventory().countItem(Items.DIAMOND)==3,"Duplicate reclamation");h.succeed();}
 @GameTest(batch="economy3",template="ng_city:empty",timeoutTicks=100) public static void storedItemsVanishAtSevenDays(GameTestHelper h){var p=player(h);account(h,p);var hotel=hotel(h);var bag=new EconomyData.Stored();bag.owner=p.getUUID();bag.since=h.getLevel().getDayTime()-7*24000;bag.items.add(new ItemStack(Items.DIAMOND));hotel.rooms[0].stored.add(bag);HotelService.tick(h.getLevel(),hotel);ok(h,hotel.rooms[0].stored.isEmpty(),"Storage deadline ignored");h.succeed();}
 @GameTest(batch="economy3",template="ng_city:empty",timeoutTicks=100) public static void onlyOwnerCanReclaimAndExplicitDisposal(GameTestHelper h){var p=player(h);account(h,p);var hotel=hotel(h);var bag=new EconomyData.Stored();bag.owner=p.getUUID();bag.since=h.getLevel().getDayTime();bag.items.add(new ItemStack(Items.DIAMOND));hotel.rooms[0].stored.add(bag);var other=player(h);account(h,other);HotelService.reclaim(other,hotel,true,false);ok(h,hotel.rooms[0].stored.size()==1,"Foreign disposal accepted");HotelService.reclaim(p,hotel,true,false);ok(h,hotel.rooms[0].stored.isEmpty()&&p.getInventory().countItem(Items.DIAMOND)==0,"Disposal did not destroy");h.succeed();}
 @GameTest(batch="economy3",template="ng_city:empty",timeoutTicks=100) public static void economySurvivesRealDiskReload(GameTestHelper h)throws Exception{var p=player(h);var a=account(h,p);var hotel=hotel(h);HotelService.book(p,hotel,0,3,false,"0427");a.wallet.set(0,new ItemStack(NgCity.CASH.get(0).get(),4));a.sales.add(new EconomyData.Receipt(System.currentTimeMillis(),123));var folder=java.nio.file.Files.createTempDirectory("ng-economy-test").toFile();var storage=new net.minecraft.world.level.storage.DimensionDataStorage(folder,h.getLevel().getServer().getFixerUpper());var factory=new net.minecraft.world.level.saveddata.SavedData.Factory<>(EconomyData::new,EconomyData::load,net.minecraft.util.datafix.DataFixTypes.LEVEL);var d=EconomyData.get(h.getLevel());storage.set("economy",d);d.setDirty();storage.save();var read=new net.minecraft.world.level.storage.DimensionDataStorage(folder,h.getLevel().getServer().getFixerUpper()).computeIfAbsent(factory,"economy");ok(h,read.accounts.get(p.getUUID()).balance==2350&&Money.total(read.accounts.get(p.getUUID()).wallet)==2000&&read.hotels.get(hotel.id).rooms[0].key.equals(hotel.rooms[0].key),"Disk persistence lost");h.succeed();}
 @GameTest(batch="economy4",template="ng_city:empty",timeoutTicks=100) public static void manufacturedBlocksFollowMaterialCost(GameTestHelper h){var l=h.getLevel();var trapdoor=BuyPrices.quote(l,new ItemStack(Items.IRON_TRAPDOOR));ok(h,trapdoor!=null&&trapdoor.units()==8&&trapdoor.quantity()==1,"Iron trapdoor must reflect four iron ingots");var stairs=BuyPrices.quote(l,new ItemStack(Items.STONE_BRICK_STAIRS));var bricks=BuyPrices.quote(l,new ItemStack(Items.STONE_BRICKS));ok(h,stairs!=null&&bricks!=null&&stairs.units()*bricks.quantity()<=bricks.units()*stairs.quantity(),"Stonecutter inflated stone value");int accepted=0;for(var item:net.minecraft.core.registries.BuiltInRegistries.ITEM)if(item instanceof BlockItem&&BuyPrices.quote(l,new ItemStack(item))!=null)accepted++;ok(h,accepted>800,"Too few Vanilla blocks accepted: "+accepted);h.succeed();}
 @GameTest(batch="economy4",template="ng_city:empty",timeoutTicks=100) public static void cashBookingReservesKeyAndChangeBeforeCharging(GameTestHelper h){var p=player(h);var hotel=hotel(h);p.getInventory().setItem(0,new ItemStack(NgCity.CASH.get(0).get()));for(int i=3;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));long before=Money.total(Money.inventory(p));HotelService.book(p,hotel,0,1,true);ok(h,hotel.rooms[0].owner==null&&Money.total(Money.inventory(p))==before,"Cash charged without room for key and change");h.succeed();}
 @GameTest(batch="economy5",template="ng_city:empty",timeoutTicks=100) public static void realDoorNeedsMatchingKeyAndIgnoresRedstone(GameTestHelper h){var p=player(h);account(h,p);var hotel=hotel(h);HotelService.book(p,hotel,0,1,false,"0427");var door=HotelService.door(hotel,0);var l=h.getLevel();var block=CityBlocks.ROOM_DOOR.get();var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(door),Direction.NORTH,door,false);block.use(l.getBlockState(door),l,door,p,InteractionHand.MAIN_HAND,hit);ok(h,!l.getBlockState(door).getValue(DoorBlock.OPEN),"Door opened without key in hand");var key=p.getInventory().items.stream().filter(x->x.is(NgCity.KEY.get())).findFirst().orElseThrow();p.setItemInHand(InteractionHand.MAIN_HAND,key.copy());block.use(l.getBlockState(door),l,door,p,InteractionHand.MAIN_HAND,hit);ok(h,l.getBlockState(door).getValue(DoorBlock.OPEN),"Matching key failed");HotelService.close(l,door);l.setBlock(door.north(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);block.neighborChanged(l.getBlockState(door),l,door,Blocks.REDSTONE_BLOCK,door.north(),false);ok(h,!l.getBlockState(door).getValue(DoorBlock.OPEN),"Redstone bypassed key");h.succeed();}
 @GameTest(batch="economy5",template="ng_city:empty",timeoutTicks=100) public static void legacyHotelUpgradesWithoutLosingStoredItems(GameTestHelper h){var l=h.getLevel();var o=CityGameTests.origin(h);var old=new BuildingPlan(BuildingKind.HOTEL,true);var plan=old.transformed(o,Direction.SOUTH);CityGameTests.support(l,plan);Placement.apply(l,plan,null,Direction.UP);var barrel=(Container)l.getBlockEntity(old.worldPos(o,Direction.SOUTH,new BlockPos(4,6,10)));barrel.setItem(0,new ItemStack(Items.DIAMOND,4));var npc=Placement.employee(l,BuildingKind.HOTEL,old.employeePos(o,Direction.SOUTH),Direction.SOUTH,UUID.randomUUID());l.addFreshEntity(npc);var hotel=HotelService.ensure(npc);ok(h,hotel.installed&&l.getBlockState(HotelService.door(hotel,0)).is(CityBlocks.ROOM_DOOR.get()),"Legacy door not migrated");ok(h,barrel.getItem(0).getCount()==4&&l.getBlockState(old.worldPos(o,Direction.SOUTH,new BlockPos(5,6,4))).isAir(),"Legacy migration lost contents or blocked hallway");h.succeed();}

 @GameTest(batch="economy_hourly",template="ng_city:empty",timeoutTicks=100) public static void oldWorldConfigGetsNewHourlyDefault(GameTestHelper h){
  var config=com.electronwill.nightconfig.core.CommentedConfig.inMemory();config.set("dailyPurchaseUnits",5000);config.set("startUnits",2500);config.set("hotelDayUnits",50);config.set("storageDayUnits",10);
  CityConfig.SPEC.correct(config);ok(h,config.getInt("hourlyPurchaseUnits")==20000,"Old world still limited to 500 euros");
  ok(h,config.getInt("startUnits")==2500&&config.getInt("hotelDayUnits")==50,"Unrelated defaults altered");
  var a=new EconomyData.Account();long now=100000000; a.sales.add(new EconomyData.Receipt(now-59*60000,9000));a.sales.add(new EconomyData.Receipt(now-1,1000));
  ok(h,a.sold(now)==10000&&a.sold(now+60000)==1000&&a.sold(now+3600000)==0,"Hourly sales window exceeds one hour");h.succeed();
 }
}
